96	/// Every media id a clip's looks name: the base look's, then each action
97	/// end's `video.look.media`, in action order, without repeats. Paste's
98	/// absorb list, after the source's media.
99	pub(crate) fn look_media_ids(clip: &Clip) -> Vec<u32> {
100	    let mut ids: Vec<u32> = Vec::new();
101	    let base = clip.video.as_ref().and_then(|video| video.look?.media);
102	    let ends = clip.actions.iter().filter_map(|action| {
103	        let media = action.end.get("video")?.get("look")?.get("media")?;
104	        u32::try_from(media.as_u64()?).ok()
105	    });
106	    for id in base.into_iter().chain(ends) {
107	        if !ids.contains(&id) {
108	            ids.push(id);
109	        }
110	    }
111	    ids
