114	/// Points a pasted clip's looks at this project's media ids. An id `map`
115	/// does not carry never stays (it could name another media here): the base
116	/// look becomes no look, and an end's look becomes `null`.
117	pub(crate) fn remap_look_media(clip: &mut Clip, map: &HashMap<u32, u32>) {
118	    if let Some(video) = clip.video.as_mut() {
119	        if let Some(id) = video.look.and_then(|look| look.media) {
120	            match map.get(&id) {
121	                Some(local) => {
122	                    if let Some(look) = video.look.as_mut() {
123	                        look.media = Some(*local);
124	                    }
125	                }
126	                None => video.look = None,
127	            }
128	        }
129	    }
130	    for action in clip.actions.iter_mut() {
131	        let Some(Value::Object(video)) = action.end.get_mut("video") else {
132	            continue;
133	        };
134	        let Some(Value::Object(look)) = video.get_mut("look") else {
135	            continue;
136	        };
137	        let Some(id) = look
138	            .get("media")
139	            .and_then(Value::as_u64)
140	            .and_then(|id| u32::try_from(id).ok())
141	        else {
142	            continue;
143	        };
144	        match map.get(&id) {
145	            Some(local) => {
146	                look.insert("media".to_string(), Value::from(*local));
147	            }
148	            None => {
149	                video.insert("look".to_string(), Value::Null);
150	            }
151	        }
152	    }
153	}
