203	    /// `remove_media` for a LUT: refused naming the clips whose base look it
204	    /// is and the media whose Camera Log it is (spec §11 GR-16) unless
205	    /// `with_clips`, which clears those looks — on the timeline and in every
206	    /// nest — and those conversions, and keeps the clips and the media. Ends
207	    /// naming it are left: the evaluator reads them as no look.
208	    pub(crate) fn remove_lut(&self, media: u32, with_clips: bool) -> Result<Outcome, String> {
209	        let used: Vec<u32> = self
210	            .every_clip()
211	            .filter(|clip| base_lut(clip) == Some(media))
212	            .map(|clip| clip.id)
213	            .collect();
214	        let converted = self.media_converted_by(media);
215	        if !with_clips {
216	            let looks = crate::edit_track::clip_list(&used);
217	            let refusal = match (used.is_empty(), converted.is_empty()) {
218	                (true, true) => None,
219	                (false, true) => Some(format!(
220	                    "media {media} is the look of {looks}; pass with_clips: true to remove it \
221	                     and clear their looks"
222	                )),
223	                (true, false) => Some(format!(
224	                    "media {media} is the Camera Log of {}; pass with_clips: true to remove it \
225	                     and clear it",
226	                    media_list(&converted)
227	                )),
228	                (false, false) => Some(format!(
229	                    "media {media} is the look of {looks} and the Camera Log of {}; pass \
230	                     with_clips: true to remove it and clear both",
231	                    media_list(&converted)
232	                )),
233	            };
234	            if let Some(refusal) = refusal {
235	                return Ok(Outcome::Refused(refusal));
236	            }
237	        }
238	        let mut next = self.clone();
239	        let clips = next
240	            .clips
241	            .iter_mut()
242	            .chain(next.nests.iter_mut().flat_map(|nest| nest.clips.iter_mut()));
243	        for clip in clips {
244	            if base_lut(clip) == Some(media) {
245	                if let Some(video) = clip.video.as_mut() {
246	                    video.look = None;
247	                }
248	            }
249	        }
250	        for row in next.media.iter_mut() {
251	            if converted.contains(&row.id) {
252	                row.color = row.color.and_then(|color| color.without_camera_log());
253	            }
254	        }
255	        next.media.retain(|m| m.id != media);
256	        self.finish(next)
257	    }
258	}
